// feedback round: profile chat, kit compass, callsign picker, thinking ETA (English; others below)
Object.assign(window.WM_I18N.dict.en, {"pq.title": "Talk to WARMIND", "pq.hello": "Callsign {name} logged. A few quick questions so I can build kits you'll enjoy.", "pq.vibe.q": "What gets you out of the hellpod?", "pq.vibe.boom": "Big booms", "pq.vibe.precision": "Every shot counts", "pq.vibe.stealth": "Ghost in the fog", "pq.vibe.hold": "Dig in and hold", "pq.vibe.any": "Surprise me", "pq.focus.q": "When the squad's in trouble, you're the one who…", "pq.focus.at": "kills the big ones", "pq.focus.ch": "mows down the horde", "pq.focus.st": "blows the objective", "pq.focus.support": "keeps everyone supplied and covered", "pq.focus.scout": "scouts ahead", "pq.focus.any": "does whatever's needed", "pq.armor.q": "Armour?", "pq.armor.Light": "Light: fast and fragile", "pq.armor.Medium": "Medium: balanced", "pq.armor.Heavy": "Heavy: walking bunker", "pq.armor.any": "Whatever fits the mission", "pq.front.q": "Favourite front?", "pq.front.terminids": "Terminids", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "All of them", "pq.done": "Logged, {name}. I'll lean your kits that way in Optimize, Fun and Improvement. Challenge and D100 will push you past it.", "pq.close": "Done", "pq.told": "Told WARMIND", "pq.nothing": "nothing yet", "pq.tune": "Talk to WARMIND", "cmp.title": "Kit compass", "cmp.say": "loud {loud}, push {push}", "cmp.loud": "LOUD", "cmp.quiet": "QUIET", "cmp.push": "PUSH", "cmp.hold": "HOLD", "cmp.w.loud.push": "Loud assault", "cmp.w.loud.hold": "Loud fortress", "cmp.w.loud.mid": "Loud", "cmp.w.quiet.push": "Quiet raider", "cmp.w.quiet.hold": "Quiet watch", "cmp.w.quiet.mid": "Quiet", "cmp.w.mid.push": "Push", "cmp.w.mid.hold": "Hold", "cmp.w.mid.mid": "Balanced", "cmp.squad": "Squad: {w}.", "cmp.hint": "Across: quiet ↔ loud (stealth kit vs statics, splash and big strikes). Up: hold ↔ push (sentries and shields vs strikes and mobility). The ring is the squad.", "mind.thinking.eta": "Usually under a minute. The kits below are ready to use now; they may update when WARMIND finishes.", "join.pick": "Been here before?", "join.pick.ph": "Pick your callsign…", "join.pick.hint": "Your last stats come back. Callsigns aren't passwords: pick your own.", "join.as": "Join as {name}"});
for (const [l, v] of Object.entries({"es": {"pq.title": "Habla con WARMIND", "pq.hello": "Indicativo {name} registrado. Unas preguntas rápidas para armar kits que disfrutes.", "pq.vibe.q": "¿Qué te saca de la cápsula?", "pq.vibe.boom": "Grandes explosiones", "pq.vibe.precision": "Cada disparo cuenta", "pq.vibe.stealth": "Fantasma en la niebla", "pq.vibe.hold": "Atrincherarse y resistir", "pq.vibe.any": "Sorpréndeme", "pq.focus.q": "Cuando el escuadrón está en apuros, eres quien…", "pq.focus.at": "abate a los grandes", "pq.focus.ch": "arrasa con la horda", "pq.focus.st": "vuela el objetivo", "pq.focus.support": "mantiene a todos abastecidos y cubiertos", "pq.focus.scout": "explora por delante", "pq.focus.any": "hace lo que haga falta", "pq.armor.q": "¿Armadura?", "pq.armor.Light": "Ligera: rápida y frágil", "pq.armor.Medium": "Media: equilibrada", "pq.armor.Heavy": "Pesada: búnker andante", "pq.armor.any": "La que encaje con la misión", "pq.front.q": "¿Frente favorito?", "pq.front.terminids": "Terminidos", "pq.front.automatons": "Autómatas", "pq.front.illuminate": "Iluminados", "pq.front.any": "Todos", "pq.done": "Registrado, {name}. Inclinaré tus kits hacia eso en Optimizar, Diversión y Mejora. Reto y D100 te empujarán más allá.", "pq.close": "Listo", "pq.told": "Le dijiste a WARMIND", "pq.nothing": "nada aún", "pq.tune": "Habla con WARMIND", "cmp.title": "Brújula de kit", "cmp.say": "ruido {loud}, empuje {push}", "cmp.loud": "RUIDOSO", "cmp.quiet": "SIGILO", "cmp.push": "EMPUJAR", "cmp.hold": "AGUANTAR", "cmp.w.loud.push": "Asalto ruidoso", "cmp.w.loud.hold": "Fortaleza ruidosa", "cmp.w.loud.mid": "Ruidoso", "cmp.w.quiet.push": "Asaltante sigiloso", "cmp.w.quiet.hold": "Vigía sigiloso", "cmp.w.quiet.mid": "Sigiloso", "cmp.w.mid.push": "Empuje", "cmp.w.mid.hold": "Aguante", "cmp.w.mid.mid": "Equilibrado", "cmp.squad": "Escuadrón: {w}.", "cmp.hint": "De lado a lado: sigilo ↔ ruido (kit sigiloso frente a estáticas, daño en área y grandes ataques). De arriba abajo: aguantar ↔ empujar (centinelas y escudos frente a ataques y movilidad). El anillo es el escuadrón.", "mind.thinking.eta": "Suele tardar menos de un minuto. Los kits de abajo ya sirven; pueden cambiar cuando WARMIND termine.", "join.pick": "¿Ya has estado aquí?", "join.pick.ph": "Elige tu indicativo…", "join.pick.hint": "Recuperas tus últimas estadísticas. Los indicativos no son contraseñas: elige el tuyo.", "join.as": "Unirse como {name}"}, "pt": {"pq.title": "Fale com a WARMIND", "pq.hello": "Codinome {name} registrado. Umas perguntas rápidas para eu montar kits de que você goste.", "pq.vibe.q": "O que te tira da cápsula?", "pq.vibe.boom": "Grandes explosões", "pq.vibe.precision": "Cada tiro conta", "pq.vibe.stealth": "Fantasma na névoa", "pq.vibe.hold": "Cavar trincheira e resistir", "pq.vibe.any": "Me surpreenda", "pq.focus.q": "Quando o esquadrão está em apuros, você é quem…", "pq.focus.at": "abate os grandalhões", "pq.focus.ch": "dizima a horda", "pq.focus.st": "explode o objetivo", "pq.focus.support": "mantém todos abastecidos e cobertos", "pq.focus.scout": "explora à frente", "pq.focus.any": "faz o que for preciso", "pq.armor.q": "Armadura?", "pq.armor.Light": "Leve: rápida e frágil", "pq.armor.Medium": "Média: equilibrada", "pq.armor.Heavy": "Pesada: bunker ambulante", "pq.armor.any": "A que servir à missão", "pq.front.q": "Frente favorita?", "pq.front.terminids": "Terminídeos", "pq.front.automatons": "Autômatos", "pq.front.illuminate": "Iluminados", "pq.front.any": "Todas", "pq.done": "Registrado, {name}. Vou inclinar seus kits nessa direção em Otimizar, Diversão e Evoluir. Desafio e D100 vão te empurrar além.", "pq.close": "Pronto", "pq.told": "Você disse à WARMIND", "pq.nothing": "nada ainda", "pq.tune": "Fale com a WARMIND", "cmp.title": "Bússola de kit", "cmp.say": "barulho {loud}, avanço {push}", "cmp.loud": "BARULHO", "cmp.quiet": "SILÊNCIO", "cmp.push": "AVANÇAR", "cmp.hold": "SEGURAR", "cmp.w.loud.push": "Assalto barulhento", "cmp.w.loud.hold": "Fortaleza barulhenta", "cmp.w.loud.mid": "Barulhento", "cmp.w.quiet.push": "Invasor silencioso", "cmp.w.quiet.hold": "Vigia silencioso", "cmp.w.quiet.mid": "Silencioso", "cmp.w.mid.push": "Avançar", "cmp.w.mid.hold": "Segurar", "cmp.w.mid.mid": "Equilibrado", "cmp.squad": "Esquadrão: {w}.", "cmp.hint": "Na horizontal: silêncio ↔ barulho (kit furtivo contra estáticas, dano em área e grandes ataques). Na vertical: segurar ↔ avançar (sentinelas e escudos contra ataques e mobilidade). O anel é o esquadrão.", "mind.thinking.eta": "Normalmente leva menos de um minuto. Os kits abaixo já podem ser usados; podem mudar quando a WARMIND terminar.", "join.pick": "Já esteve aqui?", "join.pick.ph": "Escolha seu codinome…", "join.pick.hint": "Suas últimas estatísticas voltam. Codinomes não são senhas: escolha o seu.", "join.as": "Entrar como {name}"}, "fr": {"pq.title": "Parler à WARMIND", "pq.hello": "Indicatif {name} enregistré. Quelques questions rapides pour te monter des kits qui te plaisent.", "pq.vibe.q": "Qu'est-ce qui te fait sortir de la capsule ?", "pq.vibe.boom": "De grosses explosions", "pq.vibe.precision": "Chaque tir compte", "pq.vibe.stealth": "Un fantôme dans la brume", "pq.vibe.hold": "Creuser et tenir", "pq.vibe.any": "Surprends-moi", "pq.focus.q": "Quand l'escouade est en difficulté, c'est toi qui…", "pq.focus.at": "abats les gros", "pq.focus.ch": "fauches la horde", "pq.focus.st": "fais sauter l'objectif", "pq.focus.support": "gardes tout le monde ravitaillé et couvert", "pq.focus.scout": "éclaires la route", "pq.focus.any": "fais ce qu'il faut", "pq.armor.q": "Armure ?", "pq.armor.Light": "Légère : rapide et fragile", "pq.armor.Medium": "Moyenne : équilibrée", "pq.armor.Heavy": "Lourde : bunker ambulant", "pq.armor.any": "Celle qui sert la mission", "pq.front.q": "Front préféré ?", "pq.front.terminids": "Terminides", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminés", "pq.front.any": "Tous", "pq.done": "Noté, {name}. Je pencherai tes kits dans ce sens en Optimiser, Fun et Progrès. Défi et D100 te pousseront au-delà.", "pq.close": "Terminé", "pq.told": "Dit à WARMIND", "pq.nothing": "rien pour l'instant", "pq.tune": "Parler à WARMIND", "cmp.title": "Boussole de kit", "cmp.say": "bruit {loud}, poussée {push}", "cmp.loud": "BRUYANT", "cmp.quiet": "DISCRET", "cmp.push": "POUSSER", "cmp.hold": "TENIR", "cmp.w.loud.push": "Assaut bruyant", "cmp.w.loud.hold": "Forteresse bruyante", "cmp.w.loud.mid": "Bruyant", "cmp.w.quiet.push": "Raider discret", "cmp.w.quiet.hold": "Veille discrète", "cmp.w.quiet.mid": "Discret", "cmp.w.mid.push": "Pousser", "cmp.w.mid.hold": "Tenir", "cmp.w.mid.mid": "Équilibré", "cmp.squad": "Escouade : {w}.", "cmp.hint": "En largeur : discret ↔ bruyant (kit furtif contre statiques, dégâts de zone et gros frappes). En hauteur : tenir ↔ pousser (sentinelles et boucliers contre frappes et mobilité). L'anneau, c'est l'escouade.", "mind.thinking.eta": "Moins d'une minute en général. Les kits ci-dessous sont déjà utilisables ; ils peuvent changer quand WARMIND a fini.", "join.pick": "Déjà venu ici ?", "join.pick.ph": "Choisis ton indicatif…", "join.pick.hint": "Tes dernières stats reviennent. Les indicatifs ne sont pas des mots de passe : choisis le tien.", "join.as": "Rejoindre en tant que {name}"}, "de": {"pq.title": "Sprich mit WARMIND", "pq.hello": "Rufzeichen {name} erfasst. Ein paar kurze Fragen, damit ich Kits baue, die dir Spaß machen.", "pq.vibe.q": "Was holt dich aus der Höllenkapsel?", "pq.vibe.boom": "Große Explosionen", "pq.vibe.precision": "Jeder Schuss zählt", "pq.vibe.stealth": "Geist im Nebel", "pq.vibe.hold": "Eingraben und halten", "pq.vibe.any": "Überrasch mich", "pq.focus.q": "Wenn der Trupp in Schwierigkeiten steckt, bist du derjenige, der…", "pq.focus.at": "die Großen erledigt", "pq.focus.ch": "die Horde niedermäht", "pq.focus.st": "das Ziel sprengt", "pq.focus.support": "alle versorgt und deckt", "pq.focus.scout": "vorausspäht", "pq.focus.any": "tut, was nötig ist", "pq.armor.q": "Rüstung?", "pq.armor.Light": "Leicht: schnell und zerbrechlich", "pq.armor.Medium": "Mittel: ausgewogen", "pq.armor.Heavy": "Schwer: laufender Bunker", "pq.armor.any": "Was zur Mission passt", "pq.front.q": "Lieblingsfront?", "pq.front.terminids": "Terminiden", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminaten", "pq.front.any": "Alle", "pq.done": "Erfasst, {name}. Ich neige deine Kits in Optimieren, Spaß und Verbessern in diese Richtung. Herausforderung und D100 treiben dich darüber hinaus.", "pq.close": "Fertig", "pq.told": "WARMIND gesagt", "pq.nothing": "noch nichts", "pq.tune": "Sprich mit WARMIND", "cmp.title": "Kit-Kompass", "cmp.say": "laut {loud}, Vorstoß {push}", "cmp.loud": "LAUT", "cmp.quiet": "LEISE", "cmp.push": "VORSTOSS", "cmp.hold": "HALTEN", "cmp.w.loud.push": "Lauter Angriff", "cmp.w.loud.hold": "Laute Festung", "cmp.w.loud.mid": "Laut", "cmp.w.quiet.push": "Leiser Räuber", "cmp.w.quiet.hold": "Leise Wache", "cmp.w.quiet.mid": "Leise", "cmp.w.mid.push": "Vorstoß", "cmp.w.mid.hold": "Halten", "cmp.w.mid.mid": "Ausgewogen", "cmp.squad": "Trupp: {w}.", "cmp.hint": "Horizontal: leise ↔ laut (Tarn-Kit gegen Statics, Flächenschaden und große Schläge). Vertikal: halten ↔ vorstoßen (Geschütze und Schilde gegen Schläge und Mobilität). Der Ring ist der Trupp.", "mind.thinking.eta": "Meist unter einer Minute. Die Kits unten sind sofort nutzbar; sie ändern sich evtl., wenn WARMIND fertig ist.", "join.pick": "Schon mal hier gewesen?", "join.pick.ph": "Wähle dein Rufzeichen…", "join.pick.hint": "Deine letzten Stats kommen zurück. Rufzeichen sind keine Passwörter: wähle dein eigenes.", "join.as": "Beitreten als {name}"}, "it": {"pq.title": "Parla con WARMIND", "pq.hello": "Nominativo {name} registrato. Poche domande veloci per costruire kit che ti piacciano.", "pq.vibe.q": "Cosa ti fa uscire dalla capsula?", "pq.vibe.boom": "Grandi esplosioni", "pq.vibe.precision": "Ogni colpo conta", "pq.vibe.stealth": "Fantasma nella nebbia", "pq.vibe.hold": "Scavare e resistere", "pq.vibe.any": "Sorprendimi", "pq.focus.q": "Quando la squadra è nei guai, sei tu quello che…", "pq.focus.at": "abbatte i grossi", "pq.focus.ch": "falcia l'orda", "pq.focus.st": "fa saltare l'obiettivo", "pq.focus.support": "tiene tutti riforniti e coperti", "pq.focus.scout": "fa da esploratore", "pq.focus.any": "fa quello che serve", "pq.armor.q": "Armatura?", "pq.armor.Light": "Leggera: veloce e fragile", "pq.armor.Medium": "Media: bilanciata", "pq.armor.Heavy": "Pesante: bunker ambulante", "pq.armor.any": "Quella che serve alla missione", "pq.front.q": "Fronte preferito?", "pq.front.terminids": "Terminidi", "pq.front.automatons": "Automaton", "pq.front.illuminate": "Illuminati", "pq.front.any": "Tutti", "pq.done": "Registrato, {name}. Orienterò i tuoi kit così in Ottimizza, Divertimento e Migliora. Sfida e D100 ti spingeranno oltre.", "pq.close": "Fatto", "pq.told": "Detto a WARMIND", "pq.nothing": "ancora niente", "pq.tune": "Parla con WARMIND", "cmp.title": "Bussola del kit", "cmp.say": "rumore {loud}, spinta {push}", "cmp.loud": "RUMORE", "cmp.quiet": "SILENZIO", "cmp.push": "SPINTA", "cmp.hold": "TENUTA", "cmp.w.loud.push": "Assalto rumoroso", "cmp.w.loud.hold": "Fortezza rumorosa", "cmp.w.loud.mid": "Rumoroso", "cmp.w.quiet.push": "Incursore silenzioso", "cmp.w.quiet.hold": "Sentinella silenziosa", "cmp.w.quiet.mid": "Silenzioso", "cmp.w.mid.push": "Spinta", "cmp.w.mid.hold": "Tenuta", "cmp.w.mid.mid": "Bilanciato", "cmp.squad": "Squadra: {w}.", "cmp.hint": "In orizzontale: silenzioso ↔ rumoroso (kit furtivo contro statiche, danno ad area e grandi attacchi). In verticale: tenere ↔ spingere (torrette e scudi contro attacchi e mobilità). L'anello è la squadra.", "mind.thinking.eta": "Di solito meno di un minuto. I kit qui sotto sono già utilizzabili; potrebbero cambiare quando WARMIND finisce.", "join.pick": "Sei già stato qui?", "join.pick.ph": "Scegli il tuo nominativo…", "join.pick.hint": "Le tue ultime statistiche tornano. I nominativi non sono password: scegli il tuo.", "join.as": "Entra come {name}"}, "pl": {"pq.title": "Porozmawiaj z WARMIND", "pq.hello": "Pseudonim {name} zapisany. Kilka szybkich pytań, żebym mógł budować zestawy, które polubisz.", "pq.vibe.q": "Co wyciąga cię z kapsuły?", "pq.vibe.boom": "Wielkie wybuchy", "pq.vibe.precision": "Liczy się każdy strzał", "pq.vibe.stealth": "Duch we mgle", "pq.vibe.hold": "Okopać się i trzymać", "pq.vibe.any": "Zaskocz mnie", "pq.focus.q": "Gdy drużyna ma kłopoty, to ty…", "pq.focus.at": "zabijasz tych największych", "pq.focus.ch": "kosisz hordę", "pq.focus.st": "wysadzasz cel misji", "pq.focus.support": "zaopatrujesz i osłaniasz wszystkich", "pq.focus.scout": "zwiadujesz przed drużyną", "pq.focus.any": "robisz, co trzeba", "pq.armor.q": "Pancerz?", "pq.armor.Light": "Lekki: szybki i kruchy", "pq.armor.Medium": "Średni: zrównoważony", "pq.armor.Heavy": "Ciężki: chodzący bunkier", "pq.armor.any": "Taki, jaki pasuje do misji", "pq.front.q": "Ulubiony front?", "pq.front.terminids": "Terminidzi", "pq.front.automatons": "Automatony", "pq.front.illuminate": "Iluminaci", "pq.front.any": "Wszystkie", "pq.done": "Zapisane, {name}. W trybach Optymalizacja, Zabawa i Rozwój pochylę twoje zestawy w tę stronę. Wyzwanie i D100 wypchną cię poza to.", "pq.close": "Gotowe", "pq.told": "Powiedziano WARMIND", "pq.nothing": "jeszcze nic", "pq.tune": "Porozmawiaj z WARMIND", "cmp.title": "Kompas zestawu", "cmp.say": "głośno {loud}, napór {push}", "cmp.loud": "GŁOŚNO", "cmp.quiet": "CICHO", "cmp.push": "NAPÓR", "cmp.hold": "OBRONA", "cmp.w.loud.push": "Głośny szturm", "cmp.w.loud.hold": "Głośna forteca", "cmp.w.loud.mid": "Głośny", "cmp.w.quiet.push": "Cichy najeźdźca", "cmp.w.quiet.hold": "Cicha straż", "cmp.w.quiet.mid": "Cichy", "cmp.w.mid.push": "Napór", "cmp.w.mid.hold": "Obrona", "cmp.w.mid.mid": "Zrównoważony", "cmp.squad": "Drużyna: {w}.", "cmp.hint": "Poziomo: cicho ↔ głośno (zestaw skrytobójczy kontra statyczne, obszar i duże uderzenia). Pionowo: obrona ↔ napór (działka i tarcze kontra uderzenia i mobilność). Pierścień to drużyna.", "mind.thinking.eta": "Zwykle poniżej minuty. Zestawy poniżej są gotowe do użycia; mogą się zmienić, gdy WARMIND skończy.", "join.pick": "Już tu byłeś?", "join.pick.ph": "Wybierz swój pseudonim…", "join.pick.hint": "Twoje ostatnie statystyki wrócą. Pseudonimy to nie hasła: wybierz własny.", "join.as": "Dołącz jako {name}"}, "ru": {"pq.title": "Поговорить с WARMIND", "pq.hello": "Позывной {name} записан. Пара быстрых вопросов, чтобы я собрал комплекты, которые тебе понравятся.", "pq.vibe.q": "Что вытаскивает тебя из капсулы?", "pq.vibe.boom": "Большие взрывы", "pq.vibe.precision": "Каждый выстрел на счету", "pq.vibe.stealth": "Призрак в тумане", "pq.vibe.hold": "Окопаться и держаться", "pq.vibe.any": "Удиви меня", "pq.focus.q": "Когда отряд в беде, ты тот, кто…", "pq.focus.at": "убивает крупных", "pq.focus.ch": "косит орду", "pq.focus.st": "взрывает цель", "pq.focus.support": "снабжает и прикрывает всех", "pq.focus.scout": "разведывает путь", "pq.focus.any": "делает что нужно", "pq.armor.q": "Броня?", "pq.armor.Light": "Лёгкая: быстрая и хрупкая", "pq.armor.Medium": "Средняя: сбалансированная", "pq.armor.Heavy": "Тяжёлая: ходячий бункер", "pq.armor.any": "Какая подойдёт миссии", "pq.front.q": "Любимый фронт?", "pq.front.terminids": "Терминиды", "pq.front.automatons": "Автоматоны", "pq.front.illuminate": "Иллюминаты", "pq.front.any": "Все", "pq.done": "Записано, {name}. В режимах «Оптимум», «Веселье» и «Рост» я наклоню твои комплекты в эту сторону. «Испытание» и D100 вытолкнут тебя за её пределы.", "pq.close": "Готово", "pq.told": "Сказано WARMIND", "pq.nothing": "пока ничего", "pq.tune": "Поговорить с WARMIND", "cmp.title": "Компас комплекта", "cmp.say": "шум {loud}, натиск {push}", "cmp.loud": "ШУМ", "cmp.quiet": "ТИШЬ", "cmp.push": "НАТИСК", "cmp.hold": "ОБОРОНА", "cmp.w.loud.push": "Громкий штурм", "cmp.w.loud.hold": "Громкая крепость", "cmp.w.loud.mid": "Громкий", "cmp.w.quiet.push": "Тихий рейдер", "cmp.w.quiet.hold": "Тихий дозор", "cmp.w.quiet.mid": "Тихий", "cmp.w.mid.push": "Натиск", "cmp.w.mid.hold": "Оборона", "cmp.w.mid.mid": "Сбалансированный", "cmp.squad": "Отряд: {w}.", "cmp.hint": "По горизонтали: тихо ↔ громко (скрытный комплект против стационарок, урона по площади и мощных ударов). По вертикали: оборона ↔ натиск (турели и щиты против ударов и мобильности). Кольцо — это отряд.", "mind.thinking.eta": "Обычно меньше минуты. Комплекты ниже уже готовы; они могут обновиться, когда WARMIND закончит.", "join.pick": "Бывал здесь раньше?", "join.pick.ph": "Выбери свой позывной…", "join.pick.hint": "Твоя последняя статистика вернётся. Позывные — не пароли: выбери свой.", "join.as": "Войти как {name}"}, "ja": {"pq.title": "WARMINDと話す", "pq.hello": "コールサイン {name} を記録しました。あなた好みのキットを組むために、簡単な質問をいくつか。", "pq.vibe.q": "ヘルポッドから飛び出す理由は?", "pq.vibe.boom": "ド派手な爆発", "pq.vibe.precision": "一発一発が大事", "pq.vibe.stealth": "霧の中の亡霊", "pq.vibe.hold": "陣地を固めて守る", "pq.vibe.any": "おまかせ", "pq.focus.q": "分隊がピンチのとき、あなたは…", "pq.focus.at": "大型を仕留める役", "pq.focus.ch": "大群をなぎ倒す役", "pq.focus.st": "目標を爆破する役", "pq.focus.support": "全員に補給と援護を回す役", "pq.focus.scout": "先行して偵察する役", "pq.focus.any": "必要なことは何でもやる役", "pq.armor.q": "アーマーは?", "pq.armor.Light": "軽量:速いが脆い", "pq.armor.Medium": "中量:バランス型", "pq.armor.Heavy": "重量:歩くバンカー", "pq.armor.any": "ミッション次第", "pq.front.q": "好きな戦線は?", "pq.front.terminids": "ターミニド", "pq.front.automatons": "オートマトン", "pq.front.illuminate": "イルミネイト", "pq.front.any": "全部", "pq.done": "{name}、記録しました。最適化・お楽しみ・上達ではその方向にキットを寄せます。チャレンジとD100ではそこから踏み出してもらいます。", "pq.close": "完了", "pq.told": "WARMINDに伝えた内容", "pq.nothing": "まだなし", "pq.tune": "WARMINDと話す", "cmp.title": "キットコンパス", "cmp.say": "騒音 {loud}、攻め {push}", "cmp.loud": "騒", "cmp.quiet": "静", "cmp.push": "攻", "cmp.hold": "守", "cmp.w.loud.push": "騒がしい強襲", "cmp.w.loud.hold": "騒がしい要塞", "cmp.w.loud.mid": "騒がしい", "cmp.w.quiet.push": "静かな襲撃者", "cmp.w.quiet.hold": "静かな見張り", "cmp.w.quiet.mid": "静か", "cmp.w.mid.push": "攻め", "cmp.w.mid.hold": "守り", "cmp.w.mid.mid": "バランス型", "cmp.squad": "分隊: {w}。", "cmp.hint": "横軸: 静 ↔ 騒(ステルスキット対 設置物・範囲攻撃・大技)。縦軸: 守 ↔ 攻(セントリーやシールド対 攻撃支援と機動力)。リングが分隊です。", "mind.thinking.eta": "通常は1分以内。下のキットはすぐ使えます。WARMINDの処理が終わると更新されることがあります。", "join.pick": "以前に来たことは?", "join.pick.ph": "コールサインを選択…", "join.pick.hint": "前回の成績が戻ります。コールサインはパスワードではありません。自分のものを選んでください。", "join.as": "{name} として参加"}, "ko": {"pq.title": "WARMIND와 대화", "pq.hello": "콜사인 {name} 기록 완료. 마음에 드는 키트를 짜기 위해 간단한 질문 몇 개 드릴게요.", "pq.vibe.q": "무엇이 당신을 헬팟 밖으로 끌어내나요?", "pq.vibe.boom": "큰 폭발", "pq.vibe.precision": "한 발 한 발이 중요", "pq.vibe.stealth": "안개 속의 유령", "pq.vibe.hold": "참호 파고 버티기", "pq.vibe.any": "알아서 해줘", "pq.focus.q": "분대가 위기일 때, 당신은…", "pq.focus.at": "큰 놈들을 잡는 사람", "pq.focus.ch": "대군을 쓸어버리는 사람", "pq.focus.st": "목표물을 폭파하는 사람", "pq.focus.support": "모두에게 보급과 엄호를 해주는 사람", "pq.focus.scout": "앞서 정찰하는 사람", "pq.focus.any": "필요한 건 뭐든 하는 사람", "pq.armor.q": "방어구는?", "pq.armor.Light": "경량: 빠르지만 연약", "pq.armor.Medium": "중량: 균형형", "pq.armor.Heavy": "중장: 걸어 다니는 벙커", "pq.armor.any": "임무에 맞는 것", "pq.front.q": "선호하는 전선은?", "pq.front.terminids": "테르미니드", "pq.front.automatons": "오토마톤", "pq.front.illuminate": "일루미네이트", "pq.front.any": "전부", "pq.done": "{name}, 기록했습니다. 최적화, 재미, 성장 모드에서는 키트를 그 방향으로 맞출게요. 도전과 D100은 그 너머로 밀어붙일 겁니다.", "pq.close": "완료", "pq.told": "WARMIND에게 말한 내용", "pq.nothing": "아직 없음", "pq.tune": "WARMIND와 대화", "cmp.title": "키트 나침반", "cmp.say": "소음 {loud}, 공세 {push}", "cmp.loud": "시끄러움", "cmp.quiet": "조용함", "cmp.push": "공세", "cmp.hold": "수비", "cmp.w.loud.push": "시끄러운 강습", "cmp.w.loud.hold": "시끄러운 요새", "cmp.w.loud.mid": "시끄러움", "cmp.w.quiet.push": "조용한 습격자", "cmp.w.quiet.hold": "조용한 경계", "cmp.w.quiet.mid": "조용함", "cmp.w.mid.push": "공세", "cmp.w.mid.hold": "수비", "cmp.w.mid.mid": "균형", "cmp.squad": "분대: {w}.", "cmp.hint": "가로: 조용함 ↔ 시끄러움 (은밀 키트 대 고정 설치물, 범위 피해, 대형 타격). 세로: 수비 ↔ 공세 (센트리와 방패 대 타격과 기동력). 링은 분대입니다.", "mind.thinking.eta": "보통 1분 이내. 아래 키트는 바로 쓸 수 있고, WARMIND가 끝나면 바뀔 수 있습니다.", "join.pick": "전에 와본 적 있나요?", "join.pick.ph": "콜사인을 선택하세요…", "join.pick.hint": "마지막 기록이 돌아옵니다. 콜사인은 비밀번호가 아니니 본인 것을 고르세요.", "join.as": "{name}(으)로 참가"}, "zh": {"pq.title": "与 WARMIND 对话", "pq.hello": "呼号 {name} 已记录。问几个简短的问题，好为你搭配喜欢的配装。", "pq.vibe.q": "是什么让你跳出地狱伞舱?", "pq.vibe.boom": "大爆炸", "pq.vibe.precision": "每一发都要命中", "pq.vibe.stealth": "迷雾中的幽灵", "pq.vibe.hold": "据点固守", "pq.vibe.any": "给我个惊喜", "pq.focus.q": "当小队陷入困境时，你是那个…", "pq.focus.at": "干掉大家伙的人", "pq.focus.ch": "扫平虫潮的人", "pq.focus.st": "炸毁目标的人", "pq.focus.support": "给所有人补给和掩护的人", "pq.focus.scout": "在前方侦察的人", "pq.focus.any": "缺什么补什么的人", "pq.armor.q": "护甲?", "pq.armor.Light": "轻型:快但脆", "pq.armor.Medium": "中型:均衡", "pq.armor.Heavy": "重型:移动堡垒", "pq.armor.any": "哪种适合任务就哪种", "pq.front.q": "最喜欢的战线?", "pq.front.terminids": "终结族", "pq.front.automatons": "自动机械", "pq.front.illuminate": "光能者", "pq.front.any": "全部", "pq.done": "已记录，{name}。在优化、娱乐和提升模式中，我会把你的配装往这个方向倾斜。挑战和 D100 会把你推出舒适区。", "pq.close": "完成", "pq.told": "已告诉 WARMIND", "pq.nothing": "暂无", "pq.tune": "与 WARMIND 对话", "cmp.title": "配装罗盘", "cmp.say": "响 {loud}，进 {push}", "cmp.loud": "喧", "cmp.quiet": "静", "cmp.push": "进", "cmp.hold": "守", "cmp.w.loud.push": "喧嚣强袭", "cmp.w.loud.hold": "喧嚣堡垒", "cmp.w.loud.mid": "喧嚣", "cmp.w.quiet.push": "静默突袭", "cmp.w.quiet.hold": "静默警戒", "cmp.w.quiet.mid": "安静", "cmp.w.mid.push": "进攻", "cmp.w.mid.hold": "固守", "cmp.w.mid.mid": "均衡", "cmp.squad": "小队:{w}。", "cmp.hint": "横轴:安静 ↔ 喧嚣(潜行配装对固定设施、范围伤害和大型打击)。纵轴:固守 ↔ 进攻(哨戒炮和护盾对打击和机动)。圆环代表小队。", "mind.thinking.eta": "通常不到一分钟。下面的配装现在就能用;WARMIND 完成后可能会更新。", "join.pick": "以前来过?", "join.pick.ph": "选择你的呼号…", "join.pick.hint": "你上次的数据会找回来。呼号不是密码:选你自己的。", "join.as": "以 {name} 加入"}, "hu": {"pq.title": "Beszélj a WARMIND-dal", "pq.hello": "{name} hívójel rögzítve. Pár gyors kérdés, hogy olyan felszereléseket építsek, amik tetszenek.", "pq.vibe.q": "Mi csal ki a pokolkapszulából?", "pq.vibe.boom": "Nagy durrdanások", "pq.vibe.precision": "Minden lövés számít", "pq.vibe.stealth": "Szellem a ködben", "pq.vibe.hold": "Beásni és kitartani", "pq.vibe.any": "Lepj meg", "pq.focus.q": "Ha az osztag bajban van, te vagy az, aki…", "pq.focus.at": "leteríti a nagyokat", "pq.focus.ch": "lekaszálja a hordát", "pq.focus.st": "felrobbantja a célpontot", "pq.focus.support": "mindenkit ellát és fedez", "pq.focus.scout": "előre kiderít", "pq.focus.any": "azt csinálja, ami kell", "pq.armor.q": "Páncél?", "pq.armor.Light": "Könnyű: gyors és törékeny", "pq.armor.Medium": "Közepes: kiegyensúlyozott", "pq.armor.Heavy": "Nehéz: járó bunker", "pq.armor.any": "Amelyik a küldetéshez illik", "pq.front.q": "Kedvenc front?", "pq.front.terminids": "Terminidek", "pq.front.automatons": "Automatonok", "pq.front.illuminate": "Illuminate", "pq.front.any": "Mind", "pq.done": "Rögzítve, {name}. Optimalizálás, Móka és Fejlődés módban ebbe az irányba hajlítom a felszereléseidet. A Kihívás és a D100 ezen túl fog tolni.", "pq.close": "Kész", "pq.told": "WARMIND-nak elmondva", "pq.nothing": "még semmi", "pq.tune": "Beszélj a WARMIND-dal", "cmp.title": "Felszerelés-iránytű", "cmp.say": "hangos {loud}, nyomulás {push}", "cmp.loud": "HANGOS", "cmp.quiet": "CSENDES", "cmp.push": "NYOMUL", "cmp.hold": "TARTJA", "cmp.w.loud.push": "Hangos roham", "cmp.w.loud.hold": "Hangos erőd", "cmp.w.loud.mid": "Hangos", "cmp.w.quiet.push": "Csendes portyázó", "cmp.w.quiet.hold": "Csendes őrszem", "cmp.w.quiet.mid": "Csendes", "cmp.w.mid.push": "Nyomulás", "cmp.w.mid.hold": "Tartás", "cmp.w.mid.mid": "Kiegyensúlyozott", "cmp.squad": "Osztag: {w}.", "cmp.hint": "Vízszintesen: csendes ↔ hangos (lopakodó felszerelés a statikus eszközök, területi sebzés és nagy csapások ellen). Függőlegesen: tartás ↔ nyomulás (őrtornyok és pajzsok a csapások és mozgékonyság ellen). A gyűrű az osztag.", "mind.thinking.eta": "Általában egy percnél rövidebb. Az alábbi felszerelések már használhatók; frissülhetnek, ha a WARMIND végez.", "join.pick": "Jártál már itt?", "join.pick.ph": "Válaszd ki a hívójeled…", "join.pick.hint": "Az utolsó statisztikáid visszajönnek. A hívójel nem jelszó: válaszd a sajátodat.", "join.as": "Csatlakozás mint {name}"}, "sv": {"pq.title": "Prata med WARMIND", "pq.hello": "Anropssignal {name} loggad. Några snabba frågor så jag kan bygga kit du gillar.", "pq.vibe.q": "Vad får dig ut ur helvetescapsulen?", "pq.vibe.boom": "Stora smällar", "pq.vibe.precision": "Varje skott räknas", "pq.vibe.stealth": "Spöke i dimman", "pq.vibe.hold": "Gräva ner sig och hålla stånd", "pq.vibe.any": "Överraska mig", "pq.focus.q": "När truppen har problem är det du som…", "pq.focus.at": "fäller de stora", "pq.focus.ch": "mejar ner horden", "pq.focus.st": "spränger målet", "pq.focus.support": "håller alla försörjda och täckta", "pq.focus.scout": "spanar framåt", "pq.focus.any": "gör det som behövs", "pq.armor.q": "Rustning?", "pq.armor.Light": "Lätt: snabb och bräcklig", "pq.armor.Medium": "Medel: balanserad", "pq.armor.Heavy": "Tung: gående bunker", "pq.armor.any": "Det som passar uppdraget", "pq.front.q": "Favoritfront?", "pq.front.terminids": "Terminider", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "Alla", "pq.done": "Loggat, {name}. Jag lutar dina kit åt det hållet i Optimera, Kul och Förbättra. Utmaning och D100 skjuter dig förbi det.", "pq.close": "Klar", "pq.told": "Sagt till WARMIND", "pq.nothing": "inget än", "pq.tune": "Prata med WARMIND", "cmp.title": "Kitkompass", "cmp.say": "högljudd {loud}, framstöt {push}", "cmp.loud": "HÖGLJUDD", "cmp.quiet": "TYST", "cmp.push": "FRAMSTÖT", "cmp.hold": "HÅLL", "cmp.w.loud.push": "Högljudd attack", "cmp.w.loud.hold": "Högljudd fästning", "cmp.w.loud.mid": "Högljudd", "cmp.w.quiet.push": "Tyst plundrare", "cmp.w.quiet.hold": "Tyst vakt", "cmp.w.quiet.mid": "Tyst", "cmp.w.mid.push": "Framstöt", "cmp.w.mid.hold": "Håll", "cmp.w.mid.mid": "Balanserad", "cmp.squad": "Trupp: {w}.", "cmp.hint": "Åt sidan: tyst ↔ högljudd (smygkit mot statiska, områdesskada och stora anfall). Uppåt: håll ↔ framstöt (sentries och sköldar mot anfall och rörlighet). Ringen är truppen.", "mind.thinking.eta": "Brukar ta under en minut. Kiten nedan går att använda nu; de kan uppdateras när WARMIND är klar.", "join.pick": "Varit här förut?", "join.pick.ph": "Välj din anropssignal…", "join.pick.hint": "Dina senaste stats kommer tillbaka. Anropssignaler är inga lösenord: välj din egen.", "join.as": "Gå med som {name}"}, "nl": {"pq.title": "Praat met WARMIND", "pq.hello": "Roepnaam {name} vastgelegd. Een paar snelle vragen zodat ik kits kan bouwen die je leuk vindt.", "pq.vibe.q": "Wat haalt je uit de hellpod?", "pq.vibe.boom": "Grote knallen", "pq.vibe.precision": "Elk schot telt", "pq.vibe.stealth": "Spook in de mist", "pq.vibe.hold": "Ingraven en standhouden", "pq.vibe.any": "Verras me", "pq.focus.q": "Als het squad in de problemen zit, ben jij degene die…", "pq.focus.at": "de grote jongens neerhaalt", "pq.focus.ch": "de horde maait", "pq.focus.st": "het doel opblaast", "pq.focus.support": "iedereen bevoorraadt en dekt", "pq.focus.scout": "vooruit verkent", "pq.focus.any": "doet wat nodig is", "pq.armor.q": "Pantser?", "pq.armor.Light": "Licht: snel en breekbaar", "pq.armor.Medium": "Medium: gebalanceerd", "pq.armor.Heavy": "Zwaar: wandelende bunker", "pq.armor.any": "Wat bij de missie past", "pq.front.q": "Favoriet front?", "pq.front.terminids": "Terminids", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "Allemaal", "pq.done": "Vastgelegd, {name}. In Optimaliseren, Fun en Verbeteren buig ik je kits die kant op. Uitdaging en D100 duwen je erover heen.", "pq.close": "Klaar", "pq.told": "Verteld aan WARMIND", "pq.nothing": "nog niets", "pq.tune": "Praat met WARMIND", "cmp.title": "Kitkompas", "cmp.say": "luid {loud}, druk {push}", "cmp.loud": "LUID", "cmp.quiet": "STIL", "cmp.push": "DRUK", "cmp.hold": "HOUD", "cmp.w.loud.push": "Luide aanval", "cmp.w.loud.hold": "Luide vesting", "cmp.w.loud.mid": "Luid", "cmp.w.quiet.push": "Stille plunderaar", "cmp.w.quiet.hold": "Stille wacht", "cmp.w.quiet.mid": "Stil", "cmp.w.mid.push": "Druk", "cmp.w.mid.hold": "Houd", "cmp.w.mid.mid": "Gebalanceerd", "cmp.squad": "Squad: {w}.", "cmp.hint": "Horizontaal: stil ↔ luid (stealthkit tegenover statics, splash en grote aanvallen). Verticaal: houden ↔ drukken (sentries en schilden tegenover aanvallen en mobiliteit). De ring is het squad.", "mind.thinking.eta": "Meestal minder dan een minuut. De kits hieronder zijn nu al bruikbaar; ze kunnen wijzigen als WARMIND klaar is.", "join.pick": "Hier al eens geweest?", "join.pick.ph": "Kies je roepnaam…", "join.pick.hint": "Je laatste stats komen terug. Roepnamen zijn geen wachtwoorden: kies je eigen.", "join.as": "Meedoen als {name}"}, "tl": {"pq.title": "Kausapin si WARMIND", "pq.hello": "Naka-log na ang callsign na {name}. Ilang mabilis na tanong para makabuo ako ng mga kit na magugustuhan mo.", "pq.vibe.q": "Ano ang nagpapalabas sa iyo sa hellpod?", "pq.vibe.boom": "Malalaking putok", "pq.vibe.precision": "Bawat tira ay mahalaga", "pq.vibe.stealth": "Multo sa hamog", "pq.vibe.hold": "Maghukay at manindigan", "pq.vibe.any": "Gulatin mo ako", "pq.focus.q": "Kapag nasa gipit ang squad, ikaw ang…", "pq.focus.at": "pumapatay sa mga malalaki", "pq.focus.ch": "tumutupok sa horde", "pq.focus.st": "pumuputok sa objective", "pq.focus.support": "nagbibigay ng supply at sumasaklolo sa lahat", "pq.focus.scout": "nag-i-scout sa unahan", "pq.focus.any": "gumagawa ng kung ano ang kailangan", "pq.armor.q": "Armor?", "pq.armor.Light": "Light: mabilis pero marupok", "pq.armor.Medium": "Medium: balanse", "pq.armor.Heavy": "Heavy: naglalakad na bunker", "pq.armor.any": "Kung ano ang bagay sa misyon", "pq.front.q": "Paboritong front?", "pq.front.terminids": "Terminids", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "Lahat", "pq.done": "Naka-log na, {name}. Ihihilig ko ang mga kit mo sa direksyong iyon sa Optimize, Fun at Improve. Itutulak ka naman ng Challenge at D100 lampas doon.", "pq.close": "Tapos na", "pq.told": "Sinabi kay WARMIND", "pq.nothing": "wala pa", "pq.tune": "Kausapin si WARMIND", "cmp.title": "Kit compass", "cmp.say": "maingay {loud}, tulak {push}", "cmp.loud": "MAINGAY", "cmp.quiet": "TAHIMIK", "cmp.push": "TULAK", "cmp.hold": "TIGIL", "cmp.w.loud.push": "Maingay na atake", "cmp.w.loud.hold": "Maingay na kuta", "cmp.w.loud.mid": "Maingay", "cmp.w.quiet.push": "Tahimik na raider", "cmp.w.quiet.hold": "Tahimik na bantay", "cmp.w.quiet.mid": "Tahimik", "cmp.w.mid.push": "Tulak", "cmp.w.mid.hold": "Tigil", "cmp.w.mid.mid": "Balanse", "cmp.squad": "Squad: {w}.", "cmp.hint": "Pahalang: tahimik ↔ maingay (stealth kit laban sa statics, splash at malalaking strike). Patayo: tigil ↔ tulak (sentries at shields laban sa strikes at mobility). Ang ring ang squad.", "mind.thinking.eta": "Karaniwang wala pang isang minuto. Magagamit na ang mga kit sa ibaba; maaari silang magbago kapag tapos na si WARMIND.", "join.pick": "Nakapunta ka na ba rito?", "join.pick.ph": "Piliin ang callsign mo…", "join.pick.hint": "Babalik ang huling stats mo. Hindi password ang callsign: pumili ng sarili mo.", "join.as": "Sumali bilang {name}"}, "pirate": {"pq.title": "Parley wi' WARMIND", "pq.hello": "Callsign {name} be logged in the ship's book. A few quick questions so I can rig kits ye'll fancy.", "pq.vibe.q": "What gets ye out o' the hellpod?", "pq.vibe.boom": "Big booms", "pq.vibe.precision": "Every shot counts", "pq.vibe.stealth": "Ghost in the fog", "pq.vibe.hold": "Dig in an' hold the deck", "pq.vibe.any": "Surprise me, matey", "pq.focus.q": "When the crew be in trouble, ye be the one who…", "pq.focus.at": "sinks the big beasts", "pq.focus.ch": "mows down the horde", "pq.focus.st": "blows the objective to kingdom come", "pq.focus.support": "keeps the crew stocked an' covered", "pq.focus.scout": "scouts ahead from the crow's nest", "pq.focus.any": "does whatever be needed", "pq.armor.q": "Armour?", "pq.armor.Light": "Light: quick an' fragile", "pq.armor.Medium": "Medium: well balanced", "pq.armor.Heavy": "Heavy: walkin' fortress", "pq.armor.any": "Whatever suits the mission", "pq.front.q": "Favourite front?", "pq.front.terminids": "Terminids", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "All o' them", "pq.done": "Logged, {name}. I'll lean yer kits that way in Shipshape, Shore leave an' Improve. Challenge an' D100 will push ye past it.", "pq.close": "Done", "pq.told": "Told WARMIND", "pq.nothing": "nothin' yet", "pq.tune": "Parley wi' WARMIND", "cmp.title": "Kit compass", "cmp.say": "loud {loud}, push {push}", "cmp.loud": "LOUD", "cmp.quiet": "QUIET", "cmp.push": "PUSH", "cmp.hold": "HOLD", "cmp.w.loud.push": "Loud boardin'", "cmp.w.loud.hold": "Loud fortress", "cmp.w.loud.mid": "Loud", "cmp.w.quiet.push": "Quiet raider", "cmp.w.quiet.hold": "Quiet watch", "cmp.w.quiet.mid": "Quiet", "cmp.w.mid.push": "Push", "cmp.w.mid.hold": "Hold", "cmp.w.mid.mid": "Balanced", "cmp.squad": "Crew: {w}.", "cmp.hint": "Across: quiet ↔ loud (stealth kit vs statics, splash an' big strikes). Up: hold ↔ push (sentries an' shields vs strikes an' mobility). The ring be the crew.", "mind.thinking.eta": "Usually under a minute, matey. The kits below be ready now; they may change when WARMIND finishes.", "join.pick": "Sailed here before?", "join.pick.ph": "Pick yer callsign…", "join.pick.hint": "Yer last stats come back. Callsigns ain't passwords: pick yer own.", "join.as": "Join as {name}"}, "sq": {"pq.title": "Fol me WARMIND", "pq.hello": "Emri i thirrjes {name} u regjistrua. Disa pyetje të shpejta që të ndërtoj kite që do t'i pëlqejnë.", "pq.vibe.q": "Çfarë të nxjerr nga hellpod-i?", "pq.vibe.boom": "Shpërthime të mëdha", "pq.vibe.precision": "Çdo e shtënë ka rëndësi", "pq.vibe.stealth": "Fantazmë në mjegull", "pq.vibe.hold": "Mbahu e reziston", "pq.vibe.any": "Më befaso", "pq.focus.q": "Kur skuadra është në telashe, ti je ai që…", "pq.focus.at": "vret të mëdhenjtë", "pq.focus.ch": "shuan hordhinë", "pq.focus.st": "hedh në erë objektivin", "pq.focus.support": "i mban të gjithë të furnizuar e të mbuluar", "pq.focus.scout": "zbulon përpara", "pq.focus.any": "bën çfarë duhet", "pq.armor.q": "Parzmore?", "pq.armor.Light": "E lehtë: e shpejtë dhe e brishtë", "pq.armor.Medium": "Mesatare: e baraspeshuar", "pq.armor.Heavy": "E rëndë: bunker ecës", "pq.armor.any": "Çfarëdo që i shkon misionit", "pq.front.q": "Fronti i preferuar?", "pq.front.terminids": "Terminids", "pq.front.automatons": "Automatons", "pq.front.illuminate": "Illuminate", "pq.front.any": "Të gjithë", "pq.done": "U regjistrua, {name}. Do t'i anoj kitet e tua në atë drejtim te Optimizo, Argëtim dhe Përmirësim. Sfidë dhe D100 do të të shtyjnë përtej.", "pq.close": "U krye", "pq.told": "I thatë WARMIND", "pq.nothing": "ende asgjë", "pq.tune": "Fol me WARMIND", "cmp.title": "Busulla e kitit", "cmp.say": "zhurmë {loud}, shtytje {push}", "cmp.loud": "ZHURMË", "cmp.quiet": "QETËSI", "cmp.push": "SHTYJ", "cmp.hold": "MBAJ", "cmp.w.loud.push": "Sulm i zhurmshëm", "cmp.w.loud.hold": "Kala e zhurmshme", "cmp.w.loud.mid": "I zhurmshëm", "cmp.w.quiet.push": "Sulmues i qetë", "cmp.w.quiet.hold": "Roje e qetë", "cmp.w.quiet.mid": "I qetë", "cmp.w.mid.push": "Shtytje", "cmp.w.mid.hold": "Mbajtje", "cmp.w.mid.mid": "I baraspeshuar", "cmp.squad": "Skuadra: {w}.", "cmp.hint": "Horizontalisht: i qetë ↔ i zhurmshëm (kit i fshehtë kundrejt statikave, dëmit në zonë dhe goditjeve të mëdha). Vertikalisht: mbaj ↔ shtyj (sentry dhe mburoja kundrejt goditjeve dhe lëvizshmërisë). Unaza është skuadra.", "mind.thinking.eta": "Zakonisht më pak se një minutë. Kitet më poshtë janë gati për t'u përdorur; mund të përditësohen kur WARMIND të mbarojë.", "join.pick": "Ke qenë këtu më parë?", "join.pick.ph": "Zgjidh emrin e thirrjes…", "join.pick.hint": "Statistikat e tua të fundit kthehen. Emrat e thirrjes nuk janë fjalëkalime: zgjidh të tuajin.", "join.as": "Bashkohu si {name}"}, "bs": {"pq.title": "Razgovaraj s WARMIND-om", "pq.hello": "Pozivni znak {name} zabilježen. Nekoliko brzih pitanja da napravim kitove koji će ti se svidjeti.", "pq.vibe.q": "Šta te izvlači iz hellpoda?", "pq.vibe.boom": "Veliki prasak", "pq.vibe.precision": "Svaki metak se računa", "pq.vibe.stealth": "Duh u magli", "pq.vibe.hold": "Ukopaj se i drži", "pq.vibe.any": "Iznenadi me", "pq.focus.q": "Kad je odred u nevolji, ti si taj koji…", "pq.focus.at": "obara velike", "pq.focus.ch": "kosi horde", "pq.focus.st": "diže cilj u zrak", "pq.focus.support": "drži sve opskrbljenima i pokrivenima", "pq.focus.scout": "izviđa unaprijed", "pq.focus.any": "radi šta god treba", "pq.armor.q": "Oklop?", "pq.armor.Light": "Lagani: brz i krhak", "pq.armor.Medium": "Srednji: uravnotežen", "pq.armor.Heavy": "Teški: hodajući bunker", "pq.armor.any": "Šta god odgovara misiji", "pq.front.q": "Omiljeni front?", "pq.front.terminids": "Terminidi", "pq.front.automatons": "Automatoni", "pq.front.illuminate": "Illuminate", "pq.front.any": "Svi", "pq.done": "Zabilježeno, {name}. U Optimizaciji, Zabavi i Napretku nagnut ću tvoje kitove u tom smjeru. Izazov i D100 gurnut će te dalje od toga.", "pq.close": "Gotovo", "pq.told": "Rečeno WARMIND-u", "pq.nothing": "još ništa", "pq.tune": "Razgovaraj s WARMIND-om", "cmp.title": "Kompas kita", "cmp.say": "glasno {loud}, nasrtaj {push}", "cmp.loud": "GLASNO", "cmp.quiet": "TIHO", "cmp.push": "NASRTAJ", "cmp.hold": "DRŽI", "cmp.w.loud.push": "Glasan napad", "cmp.w.loud.hold": "Glasna tvrđava", "cmp.w.loud.mid": "Glasno", "cmp.w.quiet.push": "Tihi napadač", "cmp.w.quiet.hold": "Tiha straža", "cmp.w.quiet.mid": "Tiho", "cmp.w.mid.push": "Nasrtaj", "cmp.w.mid.hold": "Držanje", "cmp.w.mid.mid": "Uravnoteženo", "cmp.squad": "Odred: {w}.", "cmp.hint": "Vodoravno: tiho ↔ glasno (stealth kit naspram statika, area štete i velikih udara). Okomito: držati ↔ nasrtati (kupole i štitovi naspram udara i pokretljivosti). Prsten je odred.", "mind.thinking.eta": "Obično manje od minute. Kitovi ispod su spremni za upotrebu; mogu se promijeniti kad WARMIND završi.", "join.pick": "Jesi li već bio ovdje?", "join.pick.ph": "Odaberi pozivni znak…", "join.pick.hint": "Tvoja zadnja statistika se vraća. Pozivni znakovi nisu lozinke: odaberi svoj.", "join.as": "Pridruži se kao {name}"}})) Object.assign(window.WM_I18N.dict[l], v);

// the armour I wear (English; others below)
Object.assign(window.WM_I18N.dict.en, {"why.worn": "Your armour, {armor} ({passive}), stays on: the kit is built around it.", "why.worn.pays": "Your armour, {armor} ({passive}), stays on, and the kit is built around it: {why}.", "why.worn.skip.d100": "D100 sets your {armor} aside: Helldive∞ is Light armour with no safety net. It's back on in every other mode.", "why.worn.skip.quiet": "A quiet run sets your {armor} aside: no Heavy armour on stealth. It's back on next drop.", "why.worn.skip.unowned": "Your {armor} isn't in your gear list, so WARMIND picked the armour. Tick it in your gear to wear it.", "arm.pick": "The armour I wear", "arm.auto": "Let WARMIND pick", "arm.q": "Do you wear one set no matter what? Pick it and I'll build every kit around it.", "arm.wear": "Wear this", "arm.saved": "From now on you wear {armor}", "arm.cleared": "WARMIND picks your armour again", "arm.hint": "Your pick stays on in every mode (D100 only keeps Light sets without a defensive passive); weapons and stratagems are chosen to use its passive.", "arm.keep": "Always wear {armor}", "arm.wearing": "Wearing your {armor}", "arm.release": "let WARMIND pick"});
for (const [l, v] of Object.entries({"es": {"why.worn": "Tu armadura, {armor} ({passive}), se queda puesta: el kit se construye en torno a ella.", "why.worn.pays": "Tu armadura, {armor} ({passive}), se queda puesta y el kit se construye en torno a ella: {why}.", "why.worn.skip.d100": "D100 aparta tu {armor}: Helldive∞ es armadura Ligera sin red de seguridad. Vuelve en el resto de modos.", "why.worn.skip.quiet": "Una misión sigilosa aparta tu {armor}: nada de armadura Pesada en sigilo. Vuelve en el próximo despliegue.", "why.worn.skip.unowned": "Tu {armor} no está en tu lista de equipo, así que WARMIND eligió la armadura. Márcala en tu equipo para llevarla.", "arm.pick": "La armadura que llevo", "arm.auto": "Que WARMIND elija", "arm.q": "¿Llevas siempre el mismo set? Elígelo y construiré cada kit en torno a él.", "arm.wear": "Llevar esta", "arm.saved": "A partir de ahora llevas {armor}", "arm.cleared": "WARMIND vuelve a elegir tu armadura", "arm.hint": "Tu elección se mantiene en todos los modos (D100 solo conserva sets Ligeros sin pasiva defensiva); las armas y los estratagemas se eligen para aprovechar su pasiva.", "arm.keep": "Llevar siempre {armor}", "arm.wearing": "Llevas tu {armor}", "arm.release": "que WARMIND elija"}, "pt": {"why.worn": "A sua armadura, {armor} ({passive}), fica vestida: o kit é montado à volta dela.", "why.worn.pays": "A sua armadura, {armor} ({passive}), fica vestida e o kit é montado à volta dela: {why}.", "why.worn.skip.d100": "D100 deixa a sua {armor} de lado: Helldive∞ é armadura Leve sem rede de segurança. Volta em todos os outros modos.", "why.worn.skip.quiet": "Uma missão furtiva deixa a sua {armor} de lado: sem armadura Pesada em furtividade. Volta no próximo drop.", "why.worn.skip.unowned": "A sua {armor} não está na sua lista de equipamento, por isso o WARMIND escolheu a armadura. Marque-a no equipamento para a usar.", "arm.pick": "A armadura que uso", "arm.auto": "Deixar o WARMIND escolher", "arm.q": "Usa sempre o mesmo set? Escolha-o e eu monto cada kit à volta dele.", "arm.wear": "Usar esta", "arm.saved": "A partir de agora usa {armor}", "arm.cleared": "O WARMIND volta a escolher a sua armadura", "arm.hint": "A sua escolha mantém-se em todos os modos (o D100 só mantém sets Leves sem passiva defensiva); armas e estratagemas são escolhidos para aproveitar a passiva.", "arm.keep": "Usar sempre {armor}", "arm.wearing": "A usar a sua {armor}", "arm.release": "deixar o WARMIND escolher"}, "fr": {"why.worn": "Ton armure, {armor} ({passive}), reste sur toi : le kit est bâti autour d'elle.", "why.worn.pays": "Ton armure, {armor} ({passive}), reste sur toi, et le kit est bâti autour d'elle : {why}.", "why.worn.skip.d100": "D100 met ton {armor} de côté : Helldive∞ est de l'armure Légère sans filet. Elle revient dans tous les autres modes.", "why.worn.skip.quiet": "Une mission discrète met ton {armor} de côté : pas d'armure Lourde en infiltration. Elle revient au prochain largage.", "why.worn.skip.unowned": "Ton {armor} n'est pas dans ta liste d'équipement, donc WARMIND a choisi l'armure. Coche-la dans ton équipement pour la porter.", "arm.pick": "L'armure que je porte", "arm.auto": "Laisser WARMIND choisir", "arm.q": "Tu portes toujours le même set ? Choisis-le et je bâtis chaque kit autour.", "arm.wear": "Porter celle-ci", "arm.saved": "Désormais tu portes {armor}", "arm.cleared": "WARMIND choisit à nouveau ton armure", "arm.hint": "Ton choix reste actif dans tous les modes (D100 ne garde que les sets Légers sans passif défensif) ; armes et stratagèmes sont choisis pour exploiter son passif.", "arm.keep": "Toujours porter {armor}", "arm.wearing": "Tu portes ton {armor}", "arm.release": "laisser WARMIND choisir"}, "de": {"why.worn": "Deine Rüstung, {armor} ({passive}), bleibt an: das Kit wird darum herum gebaut.", "why.worn.pays": "Deine Rüstung, {armor} ({passive}), bleibt an, und das Kit wird darum herum gebaut: {why}.", "why.worn.skip.d100": "D100 legt deine {armor} beiseite: Helldive∞ ist leichte Rüstung ohne Sicherheitsnetz. In allen anderen Modi ist sie wieder dabei.", "why.worn.skip.quiet": "Ein leiser Einsatz legt deine {armor} beiseite: keine schwere Rüstung beim Schleichen. Beim nächsten Drop ist sie wieder dabei.", "why.worn.skip.unowned": "Deine {armor} steht nicht in deiner Ausrüstungsliste, daher hat WARMIND die Rüstung gewählt. Hak sie in deiner Ausrüstung an, um sie zu tragen.", "arm.pick": "Die Rüstung, die ich trage", "arm.auto": "WARMIND wählen lassen", "arm.q": "Trägst du immer dasselbe Set? Wähl es aus, und ich baue jedes Kit darum herum.", "arm.wear": "Das tragen", "arm.saved": "Ab jetzt trägst du {armor}", "arm.cleared": "WARMIND wählt deine Rüstung wieder", "arm.hint": "Deine Wahl bleibt in jedem Modus aktiv (D100 behält nur leichte Sets ohne defensiven Passiv); Waffen und Stratagems werden passend zu ihrem Passiv gewählt.", "arm.keep": "Immer {armor} tragen", "arm.wearing": "Du trägst deine {armor}", "arm.release": "WARMIND wählen lassen"}, "it": {"why.worn": "La tua armatura, {armor} ({passive}), resta addosso: il kit è costruito attorno ad essa.", "why.worn.pays": "La tua armatura, {armor} ({passive}), resta addosso e il kit è costruito attorno ad essa: {why}.", "why.worn.skip.d100": "D100 mette da parte la tua {armor}: Helldive∞ è armatura Leggera senza rete di sicurezza. Torna in tutte le altre modalità.", "why.worn.skip.quiet": "Una missione silenziosa mette da parte la tua {armor}: niente armatura Pesante in stealth. Torna al prossimo lancio.", "why.worn.skip.unowned": "La tua {armor} non è nella tua lista di equipaggiamento, quindi WARMIND ha scelto l'armatura. Spuntala nell'equipaggiamento per indossarla.", "arm.pick": "L'armatura che indosso", "arm.auto": "Scelga WARMIND", "arm.q": "Indossi sempre lo stesso set? Sceglilo e costruirò ogni kit attorno a lui.", "arm.wear": "Indossa questa", "arm.saved": "D'ora in poi indossi {armor}", "arm.cleared": "WARMIND sceglie di nuovo la tua armatura", "arm.hint": "La tua scelta resta in ogni modalità (D100 tiene solo set Leggeri senza passiva difensiva); armi e stratagemmi sono scelti per sfruttarne la passiva.", "arm.keep": "Indossa sempre {armor}", "arm.wearing": "Indossi la tua {armor}", "arm.release": "scelga WARMIND"}, "pl": {"why.worn": "Twój pancerz, {armor} ({passive}), zostaje na Tobie: zestaw jest zbudowany wokół niego.", "why.worn.pays": "Twój pancerz, {armor} ({passive}), zostaje na Tobie, a zestaw jest zbudowany wokół niego: {why}.", "why.worn.skip.d100": "D100 odkłada Twój {armor}: Helldive∞ to lekki pancerz bez siatki bezpieczeństwa. W pozostałych trybach wraca.", "why.worn.skip.quiet": "Cicha misja odkłada Twój {armor}: żadnego ciężkiego pancerza w skradaniu. Wraca przy następnym zrzucie.", "why.worn.skip.unowned": "Twojego {armor} nie ma na liście sprzętu, więc WARMIND wybrał pancerz. Zaznacz go w sprzęcie, by go nosić.", "arm.pick": "Pancerz, który noszę", "arm.auto": "Niech WARMIND wybierze", "arm.q": "Zawsze nosisz ten sam zestaw? Wybierz go, a zbuduję każdy zestaw wokół niego.", "arm.wear": "Noś ten", "arm.saved": "Od teraz nosisz {armor}", "arm.cleared": "WARMIND znów wybiera Twój pancerz", "arm.hint": "Twój wybór działa w każdym trybie (D100 zostawia tylko lekkie pancerze bez pasywki obronnej); broń i stratagemy są dobierane pod jego pasywkę.", "arm.keep": "Zawsze noś {armor}", "arm.wearing": "Nosisz swój {armor}", "arm.release": "niech WARMIND wybierze"}, "ru": {"why.worn": "Твоя броня {armor} ({passive}) остаётся на тебе: набор строится вокруг неё.", "why.worn.pays": "Твоя броня {armor} ({passive}) остаётся на тебе, и набор строится вокруг неё: {why}.", "why.worn.skip.d100": "D100 убирает твою {armor}: Helldive∞ это лёгкая броня без страховки. В остальных режимах она возвращается.", "why.worn.skip.quiet": "Тихий забег убирает твою {armor}: никакой тяжёлой брони в стелсе. На следующем десанте она вернётся.", "why.worn.skip.unowned": "Твоей {armor} нет в списке снаряжения, поэтому броню выбрал WARMIND. Отметь её в снаряжении, чтобы носить.", "arm.pick": "Броня, которую я ношу", "arm.auto": "Пусть выберет WARMIND", "arm.q": "Всегда носишь один комплект? Выбери его, и я построю каждый набор вокруг него.", "arm.wear": "Носить эту", "arm.saved": "Теперь ты носишь {armor}", "arm.cleared": "WARMIND снова выбирает твою броню", "arm.hint": "Твой выбор действует во всех режимах (D100 оставляет только лёгкие комплекты без защитного перка); оружие и стратагемы подбираются под его перк.", "arm.keep": "Всегда носить {armor}", "arm.wearing": "Ты носишь {armor}", "arm.release": "пусть выберет WARMIND"}, "ja": {"why.worn": "あなたのアーマー {armor}({passive})は着たまま。キットはこれを軸に組みます。", "why.worn.pays": "あなたのアーマー {armor}({passive})は着たまま、キットはこれを軸に組みます:{why}。", "why.worn.skip.d100": "D100では{armor}は外します。Helldive∞は安全網なしの軽アーマー戦です。他のモードでは着用に戻ります。", "why.worn.skip.quiet": "静かなランでは{armor}は外します。ステルスに重アーマーは不可。次の降下では戻ります。", "why.worn.skip.unowned": "{armor}が装備リストにないため、WARMINDがアーマーを選びました。装備でチェックすると着用できます。", "arm.pick": "いつも着るアーマー", "arm.auto": "WARMINDに任せる", "arm.q": "いつも同じセットを着ますか?選んでくれれば、すべてのキットをそれ軸に組みます。", "arm.wear": "これを着る", "arm.saved": "今後は{armor}を着用", "arm.cleared": "WARMINDがアーマーを選びます", "arm.hint": "選択は全モードで有効(D100は防御パッシブのない軽セットのみ維持)。武器とストラタジェムはそのパッシブを活かすよう選ばれます。", "arm.keep": "常に{armor}を着る", "arm.wearing": "{armor}を着用中", "arm.release": "WARMINDに任せる"}, "ko": {"why.worn": "당신의 아머 {armor}({passive})는 그대로 착용합니다. 키트는 이를 중심으로 짭니다.", "why.worn.pays": "당신의 아머 {armor}({passive})는 그대로 착용하며, 키트는 이를 중심으로 짭니다: {why}.", "why.worn.skip.d100": "D100에서는 {armor}를 벗습니다. Helldive∞는 안전망 없는 경량 아머 전투입니다. 다른 모드에선 다시 착용합니다.", "why.worn.skip.quiet": "조용한 런에서는 {armor}를 벗습니다. 은신에 중량 아머는 금물입니다. 다음 강하 때 다시 착용합니다.", "why.worn.skip.unowned": "{armor}가 장비 목록에 없어서 WARMIND가 아머를 골랐습니다. 장비에서 체크하면 착용합니다.", "arm.pick": "내가 입는 아머", "arm.auto": "WARMIND에게 맡기기", "arm.q": "항상 같은 세트를 입나요? 골라 주면 모든 키트를 그 중심으로 짜겠습니다.", "arm.wear": "이걸 착용", "arm.saved": "이제부터 {armor} 착용", "arm.cleared": "WARMIND가 다시 아머를 고릅니다", "arm.hint": "선택은 모든 모드에서 유지됩니다(D100은 방어 패시브 없는 경량 세트만 유지). 무기와 스트라타젬은 그 패시브를 살리도록 고릅니다.", "arm.keep": "항상 {armor} 착용", "arm.wearing": "{armor} 착용 중", "arm.release": "WARMIND에게 맡기기"}, "zh": {"why.worn": "你的护甲 {armor}({passive})保持穿着:配装围绕它来搭。", "why.worn.pays": "你的护甲 {armor}({passive})保持穿着,配装围绕它来搭:{why}。", "why.worn.skip.d100": "D100 会把你的 {armor} 放一边:Helldive∞ 是没有保险的轻型护甲。其他模式下会重新穿上。", "why.worn.skip.quiet": "静默任务会把你的 {armor} 放一边:潜行不穿重型护甲。下次空投会重新穿上。", "why.worn.skip.unowned": "你的 {armor} 不在装备列表里,所以 WARMIND 选了护甲。在装备里勾选它即可穿上。", "arm.pick": "我穿的护甲", "arm.auto": "让 WARMIND 选", "arm.q": "你总是穿同一套吗?选好它,我会围绕它搭每一套配装。", "arm.wear": "穿这套", "arm.saved": "从现在起你穿 {armor}", "arm.cleared": "WARMIND 重新为你选护甲", "arm.hint": "你的选择在所有模式下保持(D100 只保留没有防御被动的轻型套装);武器和战略配备会按其被动来挑选。", "arm.keep": "始终穿 {armor}", "arm.wearing": "正穿着你的 {armor}", "arm.release": "让 WARMIND 选"}, "hu": {"why.worn": "A páncélod, {armor} ({passive}), rajtad marad: a felszerelés köré épül.", "why.worn.pays": "A páncélod, {armor} ({passive}), rajtad marad, és a felszerelés köré épül: {why}.", "why.worn.skip.d100": "A D100 félreteszi a(z) {armor} páncélodat: a Helldive∞ Könnyű páncél, biztonsági háló nélkül. Minden más módban visszakerül.", "why.worn.skip.quiet": "Egy csendes küldetés félreteszi a(z) {armor} páncélodat: lopakodáshoz nincs Nehéz páncél. A következő ledobásnál visszakerül.", "why.worn.skip.unowned": "A(z) {armor} nincs a felszerelés-listádon, ezért a WARMIND választott páncélt. Pipáld ki a felszerelésedben, hogy viselhesd.", "arm.pick": "A páncél, amit viselek", "arm.auto": "Döntsön a WARMIND", "arm.q": "Mindig ugyanazt a szettet viseled? Válaszd ki, és minden felszerelést köré építek.", "arm.wear": "Ezt viselem", "arm.saved": "Mostantól {armor} a viseleted", "arm.cleared": "A WARMIND újra választ páncélt", "arm.hint": "A választásod minden módban érvényes (a D100 csak a védő passzív nélküli Könnyű szetteket tartja meg); a fegyverek és stratagémok a passzívjához igazodnak.", "arm.keep": "Mindig {armor}", "arm.wearing": "{armor} van rajtad", "arm.release": "döntsön a WARMIND"}, "sv": {"why.worn": "Din rustning, {armor} ({passive}), stannar på: kitet byggs runt den.", "why.worn.pays": "Din rustning, {armor} ({passive}), stannar på, och kitet byggs runt den: {why}.", "why.worn.skip.d100": "D100 lägger din {armor} åt sidan: Helldive∞ är Lätt rustning utan skyddsnät. Den är tillbaka i alla andra lägen.", "why.worn.skip.quiet": "En tyst körning lägger din {armor} åt sidan: ingen Tung rustning i smygläge. Den är tillbaka nästa drop.", "why.worn.skip.unowned": "Din {armor} finns inte i din utrustningslista, så WARMIND valde rustningen. Bocka i den i din utrustning för att bära den.", "arm.pick": "Rustningen jag bär", "arm.auto": "Låt WARMIND välja", "arm.q": "Bär du alltid samma set? Välj det så bygger jag varje kit runt det.", "arm.wear": "Bär denna", "arm.saved": "Från nu bär du {armor}", "arm.cleared": "WARMIND väljer din rustning igen", "arm.hint": "Ditt val gäller i alla lägen (D100 behåller bara Lätta set utan defensiv passiv); vapen och stratagem väljs för att dra nytta av dess passiv.", "arm.keep": "Bär alltid {armor}", "arm.wearing": "Du bär din {armor}", "arm.release": "låt WARMIND välja"}, "nl": {"why.worn": "Je pantser, {armor} ({passive}), blijft aan: de kit wordt eromheen gebouwd.", "why.worn.pays": "Je pantser, {armor} ({passive}), blijft aan, en de kit wordt eromheen gebouwd: {why}.", "why.worn.skip.d100": "D100 legt je {armor} opzij: Helldive∞ is Licht pantser zonder vangnet. In alle andere modi is het terug.", "why.worn.skip.quiet": "Een stille run legt je {armor} opzij: geen Zwaar pantser bij stealth. Bij de volgende drop is het terug.", "why.worn.skip.unowned": "Je {armor} staat niet in je uitrusting, dus WARMIND koos het pantser. Vink het aan in je uitrusting om het te dragen.", "arm.pick": "Het pantser dat ik draag", "arm.auto": "Laat WARMIND kiezen", "arm.q": "Draag je altijd dezelfde set? Kies hem, dan bouw ik elke kit eromheen.", "arm.wear": "Draag dit", "arm.saved": "Vanaf nu draag je {armor}", "arm.cleared": "WARMIND kiest weer je pantser", "arm.hint": "Je keuze blijft aan in elke modus (D100 houdt alleen Lichte sets zonder defensieve passive); wapens en stratagems worden gekozen om de passive te benutten.", "arm.keep": "Altijd {armor} dragen", "arm.wearing": "Je draagt je {armor}", "arm.release": "laat WARMIND kiezen"}, "tl": {"why.worn": "Mananatili sa iyo ang armor mong {armor} ({passive}): ang kit ay binubuo sa paligid nito.", "why.worn.pays": "Mananatili sa iyo ang armor mong {armor} ({passive}), at ang kit ay binubuo sa paligid nito: {why}.", "why.worn.skip.d100": "Isinasantabi ng D100 ang {armor} mo: ang Helldive∞ ay Light armor na walang safety net. Babalik ito sa lahat ng ibang mode.", "why.worn.skip.quiet": "Isinasantabi ng tahimik na run ang {armor} mo: bawal ang Heavy armor sa stealth. Babalik ito sa susunod na drop.", "why.worn.skip.unowned": "Wala ang {armor} mo sa gear list mo, kaya si WARMIND ang pumili ng armor. I-tick ito sa gear mo para maisuot.", "arm.pick": "Ang armor na suot ko", "arm.auto": "Hayaan si WARMIND", "arm.q": "Iisang set ba lagi ang suot mo? Piliin mo, at bubuuin ko ang bawat kit sa paligid nito.", "arm.wear": "Isuot ito", "arm.saved": "Mula ngayon, suot mo ang {armor}", "arm.cleared": "Si WARMIND na ulit ang pipili ng armor mo", "arm.hint": "Mananatili ang pinili mo sa bawat mode (Light set lang na walang defensive passive ang pinapanatili ng D100); pinipili ang mga sandata at stratagem para magamit ang passive nito.", "arm.keep": "Laging isuot ang {armor}", "arm.wearing": "Suot mo ang {armor}", "arm.release": "hayaan si WARMIND"}, "pirate": {"why.worn": "Yer armour, {armor} ({passive}), stays on yer back: the kit be built around it.", "why.worn.pays": "Yer armour, {armor} ({passive}), stays on yer back, and the kit be built around it: {why}.", "why.worn.skip.d100": "D100 stows yer {armor}, matey: Helldive∞ be Light armour with no safety net. She's back on in every other mode.", "why.worn.skip.quiet": "A quiet run stows yer {armor}: no Heavy armour when sneakin'. She's back on next drop.", "why.worn.skip.unowned": "Yer {armor} ain't in yer gear list, so WARMIND picked the armour. Tick it in yer gear to wear it.", "arm.pick": "The armour I wear", "arm.auto": "Let WARMIND pick", "arm.q": "Ye wear one set come hell or high water? Pick it and I'll build every kit around it, savvy?", "arm.wear": "Wear this", "arm.saved": "From now on ye wear {armor}", "arm.cleared": "WARMIND picks yer armour again", "arm.hint": "Yer pick stays on in every mode (D100 only keeps Light sets without a defensive passive); weapons and stratagems be chosen to use its passive.", "arm.keep": "Always wear {armor}", "arm.wearing": "Wearin' yer {armor}", "arm.release": "let WARMIND pick"}, "sq": {"why.worn": "Armatura jote, {armor} ({passive}), mbetet veshur: kiti ndërtohet rreth saj.", "why.worn.pays": "Armatura jote, {armor} ({passive}), mbetet veshur dhe kiti ndërtohet rreth saj: {why}.", "why.worn.skip.d100": "D100 e lë mënjanë {armor} tënde: Helldive∞ është armaturë e lehtë pa rrjetë sigurie. Kthehet në çdo mënyrë tjetër.", "why.worn.skip.quiet": "Një mision i qetë e lë mënjanë {armor} tënde: pa armaturë të rëndë në fshehtësi. Kthehet në rënien tjetër.", "why.worn.skip.unowned": "{armor} jote nuk është në listën e pajisjeve, ndaj WARMIND zgjodhi armaturën. Shëno atë te pajisjet për ta veshur.", "arm.pick": "Armatura që vesh", "arm.auto": "Le të zgjedhë WARMIND", "arm.q": "E vesh gjithmonë të njëjtin set? Zgjidhe dhe unë do ta ndërtoj çdo kit rreth tij.", "arm.wear": "Vishe këtë", "arm.saved": "Tani e tutje vesh {armor}", "arm.cleared": "WARMIND zgjedh përsëri armaturën tënde", "arm.hint": "Zgjedhja jote mbetet në çdo mënyrë (D100 mban vetëm sete të lehta pa pasiv mbrojtës); armët dhe stratagemat zgjidhen për të përdorur pasivin e saj.", "arm.keep": "Vishe gjithmonë {armor}", "arm.wearing": "Po vesh {armor} tënde", "arm.release": "le të zgjedhë WARMIND"}, "bs": {"why.worn": "Tvoj oklop, {armor} ({passive}), ostaje na tebi: kit se gradi oko njega.", "why.worn.pays": "Tvoj oklop, {armor} ({passive}), ostaje na tebi, a kit se gradi oko njega: {why}.", "why.worn.skip.d100": "D100 odlaže tvoj {armor}: Helldive∞ je Lahki oklop bez sigurnosne mreže. U svim ostalim modovima se vraća.", "why.worn.skip.quiet": "Tiha misija odlaže tvoj {armor}: nema Teškog oklopa u stealthu. Vraća se na sljedećem spuštanju.", "why.worn.skip.unowned": "Tvog {armor} nema na listi opreme, pa je WARMIND odabrao oklop. Označi ga u opremi da ga nosiš.", "arm.pick": "Oklop koji nosim", "arm.auto": "Neka WARMIND odabere", "arm.q": "Uvijek nosiš isti set? Odaberi ga i napravit ću svaki kit oko njega.", "arm.wear": "Nosi ovo", "arm.saved": "Od sada nosiš {armor}", "arm.cleared": "WARMIND ponovo bira tvoj oklop", "arm.hint": "Tvoj izbor važi u svim modovima (D100 zadržava samo Lahke setove bez odbrambenog pasiva); oružje i stratagemi biraju se da iskoriste njegov pasiv.", "arm.keep": "Uvijek nosi {armor}", "arm.wearing": "Nosiš svoj {armor}", "arm.release": "neka WARMIND odabere"}})) Object.assign(window.WM_I18N.dict[l], v);

